	subtitle = "Уцелевший из Дарроушира",
	found = "Часовня Последней Надежды",
	hint = [=[Ищите скорбящего уроженца Дарроушира, который служит Рассвету в Часовне Последней Надежды.]=],
	allegiance = "Серебряный Рассвет",
	aliases = { "Карлин", "брат Карлин", "дядя Карлин" },
	sections = {
		{
			title = "Обзор",
			text = [=[Карлин Редпат — солдат {link:argent-dawn}Серебряного Рассвета{/link} в Часовне Последней Надежды. Он родился в {link:darrowshire}Дарроушир{/link}е и один из очень немногих, кто пережил битву, уничтожившую деревню. Его братом был {link:joseph-redpath}капитан Джозеф Редпат{/link}, который возглавлял оборону деревни. Его маленькая племянница, {link:pamela-redpath}Памела{/link}, мертва. Карлин обратил свое горе в одну-единственную цель: отмщение Плети, отнявшей его дом.]=],
		},
		{
			title = "Значение",
			text = [=[Карлин — живая память {link:darrowshire}Дарроушир{/link}а. Его герои, его злодеи и его мертвые взывают к нему во снах. Когда ему принесли «Анналы Дарроушира», он узнал, что еще может сделать для них больше, чем скорбеть.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он пережил битву за {link:darrowshire}Дарроушир{/link} и предательство брата.
• Он служит Серебряному Рассвету в Часовне Последней Надежды.
• Он собрал реликвии битвы за Дарроушир, чтобы судьбу деревни можно было изменить.]=],
		},
	},
	chapters = {
		{
			title = "Дядя Карлин",
			hint = [=[Принесите ему весть о маленькой девочке, которая все еще ждет в Дарроушире.]=],
			text = [=[Карлин верил, что {link:pamela-redpath}Памела{/link}, может быть, жива. Когда он узнал, что она мертва и все еще ждет призраком, он вскричал, что в тот же миг поменялся бы с ней местами. Потом он отложил горе и попросил освободить от Плети истерзанные души защитников {link:darrowshire}Дарроушир{/link}а, ибо многие из них теперь служат ей вурдалаками и живодерами.]=],
		},
		{
			title = "Анналы Дарроушира",
			hint = [=[Принесите «Дополненные Анналы Дарроушира» в Часовню Последней Надежды.]=],
			text = [=[Странная {link:gnomes}гном{/link}ка в {link:ruins-of-andorhal}Андорал{/link}е сотворила над «Анналами {link:darrowshire}Дарроушир{/link}а» свою магию, и в конце книги появились новые страницы. Они рассказывали о днях после битвы, и одна из них говорила о нем самом. Карлин прочел их и не мог понять, правда ли это. Он решил выяснить.]=],
		},
		{
			title = "Герои и злодеи",
			hint = "Соберите реликвии героев и злодеев Дарроушира.",
			text = [=[«Анналы» назвали их всех. Манускрипт паладина {link:davil-lightfire}Давил{/link}а {link:holy-light}Свет{/link}лого Пламени унесли в {link:hearthglen}Дольный Очаг{/link}. Треснувший щит капитана {link:marshal-redpath}Редпат{/link}а лежал возле амбара на западе. Череп повелителя вурдалаков {link:horgus-the-ravager}Хоргус{/link}а лежал в озере, а сломанный меч злодея {link:magistrate-marduke}Мардук{/link}а Черного — в ущелье возле Перекрестка Корина. Последними были черепа воителей Плети, сражавшихся в той битве. Карлин не вполне понимал, почему эти реликвии важны. Он лишь чувствовал, что они связаны с его домом.]=],
		},
		{
			title = "Возвращение к Хроми",
			hint = "Отправьте реликвии Дарроушира гномке в Андорал.",
			text = [=[Когда все реликвии были собраны, Карлин отправил их на запад, {link:gnomes}гном{/link}ке {link:chromie}Хроми{/link}, в разрушенную таверну {link:ruins-of-andorhal}Андорал{/link}а. Она сказала ему то, во что он едва смел верить: что {link:darrowshire}Дарроушир{/link} можно спасти.]=],
		},
	},
	mentions = {
		{ text = "«Дядя Карлин»" },
		{ text = "«Защитники {link:darrowshire}Дарроушир{/link}а»" },
		{ text = "«Брат Карлин»" },
		{ text = "«Герои {link:darrowshire}Дарроушир{/link}а»" },
		{ text = "«Злодеи {link:darrowshire}Дарроушир{/link}а»" },
		{ text = "«Разорители {link:darrowshire}Дарроушир{/link}а»" },
		{ text = "«Возвращение к {link:chromie}Хроми{/link}»" },
	},
	bonds = {
		{ id = "joseph-redpath", name = "Джозеф Редпат", note = "его брат" },
		{ id = "pamela-redpath", name = "Памела Редпат", note = "его племянница" },
		{ id = "marshal-redpath", name = "маршал Редпат", note = "носит то же имя; о родстве записей нет" },
		{ id = "lord-maxwell-tyrosus", name = "лорд Максвелл Тиросус", note = "возглавляет его братство" },
	},
})

Translate("ruRU", "pamela-redpath", {
	title = "Памела Редпат",
	subtitle = "Дитя Дарроушира",
	found = "Дом ее семьи, к югу от руин Дарроушира",
	hint = [=[Ищите маленькую девочку, которая ждет в доме к югу от Дарроушира.]=],
	allegiance = "Дарроушир",
	aliases = { "Памела", "маленькая Памела" },
	sections = {
		{
			title = "Обзор",
			text = [=[Памела Редпат — призрак маленькой девочки из {link:darrowshire}Дарроушир{/link}а. Когда пришла {link:scourge}Плеть{/link}, ее отец, {link:joseph-redpath}капитан Джозеф Редпат{/link}, ушел сражаться, а тетя {link:marlene-redpath}Марлен{/link} велела ей остаться в доме и спрятаться. С тех пор она там и ждет. Она не знает, что мертва. Она не знает, что сталось с ее отцом. Она знает только, что он за ней не пришел, что в темноте ей иногда шепчут дурные голоса и что она оставила свою куклу в деревне.]=],
		},
		{
			title = "Значение",
			text = [=[Памела — самый печальный из призраков Чумных земель и тот, что тронул больше всего сердец. Ее тетя, ее дядя и ее сестра — каждый просил чужих людей ее найти. Через нее история {link:darrowshire}Дарроушир{/link}а и семьи {link:marshal-redpath}Редпат{/link}ов снова выходит на свет.]=],
		},
		{
			title = "Ее семья",
			text = [=[Ее отцом был {link:joseph-redpath}капитан Джозеф Редпат{/link}, который возглавлял оборону {link:darrowshire}Дарроушир{/link}а. Ее тетя {link:marlene-redpath}Марлен{/link} спрятала ее, когда началась битва, и теперь бродит духом возле {link:ruins-of-andorhal}Андорал{/link}а. Ее {link:carlin-redpath}дядя Карлин{/link} служит Серебряному Рассвету в Часовне Последней Надежды. Ее старшая сестра {link:jessica-redpath}Джессика{/link} бежала из {link:lordaeron}Лордерон{/link}а до чумы и живет далеко, в {link:winterspring}Зимних Ключах{/link}. Памела помнит, что Джессика плакала, уезжая, и не понимает почему.]=],
		},
	},
	chapters = {
		{
			title = "Маленькая Памела",
			hint = "Найдите ребенка, которого разыскивает ее родня.",
			text = [=[Памела поздоровалась с гостем и спросила его имя. Она говорила об отце, самом храбром человеке на всем свете, и о сестре, с которой они прятались вместе и выскакивали, чтобы удивить отца, когда он приходил домой.]=],
		},
		{
			title = "Кукла маленькой Памелы",
			hint = "Найдите куклу, которую девочка оставила в деревне.",
			text = [=[Кукла лежала где-то в руинах {link:darrowshire}Дарроушир{/link}а, где до сих пор ходят мертвые. Когда ее нашли и принесли, Памела была вне себя от радости. Это было первое, что утешило ее за очень долгое время.]=],
		},
		{
			title = "Битва за Дарроушир",
			hint = "Примите участие в битве за Дарроушир и верните отца домой.",
			text = [=[Заклинанием {link:gnomes}гном{/link}ки {link:chromie}Хроми{/link} битва за {link:darrowshire}Дарроушир{/link} была разыграна вновь среди ее призраков. На этот раз {link:joseph-redpath}капитан Редпат{/link} был спасен. Когда бой закончился, Памела услышала, как отец шепчет ей. Он сказал, что прогнал призраков и идет домой. Она заварила чай, положив очень много сахара, для того, кто ему помог. Потом она дала этому другу ключ от отца, который открывал сундук, спрятанный за домом.]=],
		},
	},
	mentions = {
		{ text = "«Сестренка Памела»" },
		{ text = "«Маленькая Памела»" },
		{ text = "«Кукла маленькой Памелы»" },
		{ text = "«Тетушка {link:marlene-redpath}Марлен{/link}»" },
		{ text = "«Дядя {link:carlin-redpath}Карлин{/link}»" },
		{ text = "«Битва за {link:darrowshire}Дарроушир{/link}»" },
		{ text = "«Спрятанные сокровища»" },
	},
	bonds = {
		{ id = "joseph-redpath", name = "Джозеф Редпат", note = "ее отец" },
		{ id = "carlin-redpath", name = "Карлин Редпат", note = "ее дядя" },
		{ id = "marlene-redpath", name = "Марлен Редпат", note = "ее тетя, которая ее спрятала" },
		{ id = "jessica-redpath", name = "Джессика Редпат", note = "ее старшая сестра" },
	},
})

